#!/usr/bin/env node
/**
 * ===========================================================================
 * TIER-0 · EVERY SUPPORTED FORMAT, FROM THE FILE TO THE COMMAND CENTRE.
 * ===========================================================================
 *
 * For each format `fileTypes.pure.ts` accepts, one document of the run's own
 * (`scripts/ops/fixtures/tier0`, digests pinned in its manifest, generated by
 * `scripts/stock-acceptance/make-tier0-fixtures.py`, nothing in it any
 * customer's) is imported into an organisation of its own, the way a
 * builder's browser imports it, and followed all the way:
 *
 *   1. PARSED     — every property the document states, and nothing else;
 *   2. STORED     — field by field against what the DOCUMENT states
 *                   (expectations authored from the document, never from a
 *                   run of the reader);
 *   3. SERVED     — the Builder Portal's own `list_stock` / `get_stock_item`
 *                   answer the same values;
 *   4. PUBLISHED  — by the product's own settler and publication gate. A
 *                   document that carries no photograph of a property is
 *                   given one through the builder's own "Add picture" path,
 *                   which is the product's documented remedy, and nothing
 *                   here writes a lifecycle;
 *   5. TRANSFERRED over a proof-only transport to the LIVE Command Centre
 *                   door, signed, by the product's own trigger, outbox and
 *                   worker;
 *   6. RECEIVED   — the Command Centre's mirror holds the same values;
 *   7. READ       — the Command Centre's own `get_stock_item` answers them to
 *                   a staff session, with a photograph whose bytes it serves.
 *
 * Every wait is the product's own time, recorded. Every row and object is
 * deleted on both sides at the end and the deletion is counted.
 *
 * Runs from the production-rollout workflow (phase `stock-tier0-formats`).
 * `TIER0_ONLY` (comma-separated keys) narrows a run to some formats.
 */
import {
  RUN, record, results, net, cc, sleep, id, sha256, secs, waitFor, stock, commandCentre,
  fixture, manifest, storageFor, withLinks, seedOrganisation, connectTransport, seedStaff,
  uploadDocument, uploadRow, waitImported, itemsOf, differences, mirrorOf, cleanup, leftovers,
  finish, ITEM_FIELDS, CC_FIELDS, NETWORK_REF, sqlLit, printPropertyEvidence,
} from './tier0/common.mjs';

const TAG = 'tier0-formats';
const ONLY = String(process.env.TIER0_ONLY || '').split(',').map((s) => s.trim()).filter(Boolean);
const BATCH = Number(process.env.TIER0_BATCH || 5);
const IMPORT_DEADLINE_MS = 10 * 60_000;
const PUBLISH_DEADLINE_MS = 18 * 60_000;
const MIRROR_DEADLINE_MS = 8 * 60_000;

/*
 * What each document STATES. A table states every column of the schedule; the
 * two PDFs state less, and a field a document does not state is not asserted.
 */
const ALL = ITEM_FIELDS;
const SCHEDULE = ['lot_number', 'address_line', 'house_design', 'bedrooms', 'bathrooms', 'car_spaces',
  'land_size_sqm', 'building_size_sqm', 'price'];
const BROCHURE = ['lot_number', 'address_line', 'suburb', 'state', 'postcode', 'development_name',
  'house_design', 'land_size_sqm', 'building_size_sqm', 'price'];
const CASES = [
  { key: 'csv-v1', file: 'csv-v1.csv', links: true, photos: 'linked', fields: ALL },
  { key: 'tsv', file: 'tsv.tsv', links: true, photos: 'linked', fields: ALL },
  { key: 'txt', file: 'txt.txt', links: true, photos: 'linked', fields: ALL },
  { key: 'html', file: 'html.html', links: true, photos: 'linked', fields: ALL },
  { key: 'json', file: 'json.json', links: true, photos: 'linked', fields: ALL },
  { key: 'xml', file: 'xml.xml', links: true, photos: 'linked', fields: ALL },
  { key: 'xlsx', file: 'xlsx.xlsx', photos: 'embedded', fields: ALL },
  { key: 'xlsx-defaultns', file: 'xlsx-defaultns.xlsx', photos: 'embedded', fields: ALL },
  { key: 'xlsm', file: 'xlsm.xlsm', photos: 'embedded', fields: ALL },
  { key: 'xls', file: 'xls.xls', photos: 'limitation', fields: ALL,
    limitation: 'a legacy .xls carries its pictures in a container the reader does not open, and the import says so' },
  { key: 'ods', file: 'ods.ods', photos: 'embedded', fields: ALL },
  { key: 'docx', file: 'docx.docx', photos: 'embedded', fields: ALL },
  { key: 'odt', file: 'odt.odt', photos: 'embedded', fields: ALL },
  { key: 'doc', file: 'doc.doc', photos: 'embedded', fields: ALL, refusal: /older Word \(\.doc\) file/ },
  { key: 'rtf', file: 'rtf.rtf', photos: 'limitation', fields: ALL,
    limitation: 'the RTF reader recovers the table and no pictures' },
  { key: 'pptx', file: 'pptx.pptx', photos: 'embedded', fields: ALL },
  { key: 'pdf-schedule', file: 'pdf-schedule.pdf', photos: 'limitation', fields: SCHEDULE,
    limitation: 'pictures on a page several properties share are kept for the builder to place, never guessed' },
  { key: 'pdf-brochure', file: 'pdf-brochure.pdf', photos: 'embedded', fields: BROCHURE, caseless: true },
  { key: 'png', file: 'png.png', photos: 'none', fields: ALL, refusal: /Photographs and scans of a stock list/ },
  { key: 'jpg', file: 'jpg.jpg', photos: 'none', fields: ALL, refusal: /Photographs and scans of a stock list/ },
  { key: 'webp', file: 'webp.webp', photos: 'none', fields: ALL, refusal: /Photographs and scans of a stock list/ },
  { key: 'gif', file: 'gif.gif', photos: 'none', fields: ALL, refusal: /Photographs and scans of a stock list/ },
].filter((c) => !ONLY.length || ONLY.includes(c.key));

/** A photograph a builder would choose, from the pinned media, for the remedy. */
const REMEDY_PHOTO = () => fixture('media/remedy.jpg');

const matrix = [];

async function runCase(c, storage, staff) {
  const row = { format: c.key, file: c.file };
  matrix.push(row);
  const org = await seedOrganisation(TAG, c.key.replace(/[^a-z0-9]/g, ''));
  await connectTransport(TAG, org);
  const want = manifest().expect[c.key];
  row.expected = want.length;

  // 1. The three requests a builder's browser makes.
  let bytes = fixture(c.file);
  if (c.links) bytes = new TextEncoder().encode(await withLinks(storage, org.orgId, new TextDecoder().decode(bytes)));
  const started = Date.now();
  const sent = await uploadDocument(org.cookie, c.file, bytes);
  row.processUpload = sent.processed?.status ?? sent.refusedAt;
  /*
   * A FILE THIS DEPLOYMENT CANNOT READ IS REFUSED, AND SAYS WHY. A photograph
   * of a list is read by the assisted reader alone, which production has off,
   * and the legacy Word reader recovers no table: the product's answer for
   * both is a refusal naming what to upload instead — never "it did not
   * describe a property" about a document nothing read.
   */
  if (c.refusal) {
    const said = String(sent.processed?.json?.error ?? '');
    record(`${c.key}: the product refuses a file it cannot read, and tells the builder what to upload instead`,
      sent.processed?.status === 400 && c.refusal.test(said),
      `create ${sent.created?.status}, put ${sent.put ?? '—'}, process ${sent.processed?.status ?? '—'} (${said.slice(0, 160)})`);
    row.verdict = 'refused (limitation)';
    return;
  }
  if (!record(`${c.key}: the upload is accepted and processed`, !!sent.uploadId && sent.processed?.status === 200,
    `create ${sent.created?.status}, put ${sent.put ?? '—'}, process ${sent.processed?.status ?? '—'}`
    + `${sent.processed?.json?.error ? ` (${String(sent.processed.json.error).slice(0, 120)})` : ''}`)) {
    row.verdict = 'refused'; return;
  }
  const imported = await waitImported(sent.uploadId, IMPORT_DEADLINE_MS);
  row.importMs = Date.now() - started;
  const upload = imported.upload;
  record(`${c.key}: the import finished by itself`, imported.done,
    `${upload?.status} via ${upload?.parse_strategy ?? '—'} in ${secs({ ms: row.importMs })}; `
    + `detected ${upload?.records_detected}, imported ${upload?.records_imported}, failed ${upload?.records_failed}`
    + `${upload?.error_code ? `, error ${upload.error_code}` : ''}`);

  // 2. Stored, field by field, against what the document states.
  const items = await itemsOf(org.orgId);
  const expected = want.map((w) => Object.fromEntries(Object.entries(w).filter(([k]) => c.fields.includes(k))));
  const have = c.caseless
    ? items.map((i) => Object.fromEntries(Object.entries(i).map(([k, v]) => [k, typeof v === 'string' ? v.toLowerCase() : v])))
    : items;
  const wantCased = c.caseless
    ? expected.map((w) => Object.fromEntries(Object.entries(w).map(([k, v]) => [k, typeof v === 'string' ? v.toLowerCase() : v])))
    : expected;
  const diff = differences(wantCased, have, c.fields);
  row.properties = items.length;
  row.parsed = diff.length === 0 ? 'exact' : `${diff.length} difference(s)`;
  record(`${c.key}: every property the document states, stored field by field`, diff.length === 0,
    diff.length ? diff.slice(0, 12).join('; ') : `${items.length} properties, ${c.fields.length} fields each, exact`);

  // 3. Served by the Builder Portal's own reads.
  const listed = await stock({ operation: 'list_stock', lifecycle_status: 'staged', page_size: 50 }, org.cookie);
  const listedActive = await stock({ operation: 'list_stock', page_size: 50 }, org.cookie);
  // One property, once: a list that publishes BETWEEN the two reads is served
  // by both (staged, then active), which is the product working, not a copy.
  const served = [...new Map([...(listed.json?.items ?? listed.json?.records ?? []),
    ...(listedActive.json?.items ?? listedActive.json?.records ?? [])].map((row) => [row.id, row])).values()];
  const servedDiff = differences(items.map((i) => ({ ...i })), served,
    ['address_line', 'suburb', 'state', 'postcode', 'bedrooms', 'bathrooms', 'car_spaces', 'land_size_sqm',
      'building_size_sqm', 'price', 'price_display', 'availability_status'], 'lot_number');
  record(`${c.key}: the Builder Portal's Stock List read answers the stored values`,
    listed.status === 200 && listedActive.status === 200 && servedDiff.length === 0,
    `HTTP ${listed.status}/${listedActive.status}, ${served.length} served`
    + `${servedDiff.length ? `; ${servedDiff.slice(0, 6).join('; ')}` : ''}`);
  if (items[0]) {
    const one = await stock({ operation: 'get_stock_item', stock_item_id: items[0].id }, org.cookie);
    const record0 = one.json?.item ?? one.json?.record ?? null;
    record(`${c.key}: get_stock_item answers the stored property`,
      one.status === 200 && record0?.id === items[0].id && String(record0?.lot_number) === String(items[0].lot_number),
      `HTTP ${one.status}`);
  }

  // 4. Published by the product. A property its document gave no photograph
  // of is given one the way a builder does it — never by writing a lifecycle.
  let remedied = 0;
  const publishStarted = Date.now();
  const waitReady = async (deadline) => waitFor(`${c.key} publication`, async () => {
    const now = await itemsOf(org.orgId);
    const u = await uploadRow(sent.uploadId);
    // The image engine's own terminal answers: a property is live, or its
    // work is `settled` / `failed` and nothing further will happen unaided.
    // A property whose OWN photograph is ready (the product's publication rule,
    // `builder_stock_photo_is_source_ready`) is not waiting on the builder: it
    // is waiting on the publication sweep, so it is waited for, not remedied.
    const final = now.every((i) => i.lifecycle_status === 'active'
      || (['settled', 'failed'].includes(i.image_work_stage) && !i.photo_ready));
    return { done: now.length > 0 && final, now, upload: u };
  }, deadline, 10_000);
  let ready = await waitReady(PUBLISH_DEADLINE_MS);
  const photoless = (ready.now ?? []).filter((i) => i.lifecycle_status !== 'active' && !i.photo_ready);
  const readyButUnpublished = (ready.now ?? []).filter((i) => i.lifecycle_status !== 'active' && i.photo_ready);
  if (readyButUnpublished.length) {
    record(`${c.key}: every property with its own ready photograph is published without help`, false,
      `${readyButUnpublished.length} ready but not live after ${secs({ ms: Date.now() - publishStarted })}; `
      + `blocked: ${ready.upload?.publication_blocked_reason ?? '—'}`);
  }
  row.fromDocument = (ready.now ?? []).length - photoless.length;
  if (photoless.length) {
    for (const item of photoless) {
      const made = await stock({ operation: 'create_builder_image', filename: 'facade.jpg', stock_item_id: item.id }, org.cookie);
      if (made.status !== 200 || !made.json?.upload_url) continue;
      const put = await fetch(made.json.upload_url, { method: 'PUT', headers: { 'Content-Type': 'image/jpeg' }, body: REMEDY_PHOTO() });
      if (!put.ok) continue;
      const attached = await stock({ operation: 'attach_builder_image', storage_path: made.json.storage_path, stock_item_id: item.id }, org.cookie);
      if (attached.status === 200) remedied += 1;
    }
    row.remedied = remedied;
    record(`${c.key}: ${photoless.length} propert${photoless.length === 1 ? 'y' : 'ies'} the document gave no usable photograph of`
      + ' — the builder adds one through "Add picture"', remedied === photoless.length,
    `${remedied}/${photoless.length} attached; blocked reason: ${ready.upload?.publication_blocked_reason ?? '—'}`,
    { required: c.photos === 'none' });
    if (c.photos === 'limitation') {
      record(`${c.key}: the document's own photographs reached every property it states`, false,
        `PARTIAL by design — ${c.limitation}; ${photoless.length} of ${(ready.now ?? []).length} needed a builder-supplied picture`,
        { required: false });
    } else if (c.photos !== 'none') {
      record(`${c.key}: the document's own photographs reached every property it states`, false,
        `${photoless.length} of ${(ready.now ?? []).length} needed a builder-supplied picture`);
    }
    ready = await waitFor(`${c.key} publication after the remedy`, async () => {
      const now = await itemsOf(org.orgId);
      const u = await uploadRow(sent.uploadId);
      return { done: now.every((i) => i.lifecycle_status === 'active'), now, upload: u };
    }, PUBLISH_DEADLINE_MS, 10_000);
  }
  row.publishMs = Date.now() - publishStarted;
  const active = (ready.now ?? []).filter((i) => i.lifecycle_status === 'active');
  row.published = `${active.length}/${(ready.now ?? []).length}`;
  record(`${c.key}: the product published every property`, ready.done && active.length === (ready.now ?? []).length,
    `${active.length}/${(ready.now ?? []).length} active in ${secs({ ms: row.publishMs })}; `
    + `upload published_at ${ready.upload?.published_at ? 'set' : 'null'}; blocked: ${ready.upload?.publication_blocked_reason ?? '—'}`);
  if (!active.length) {
    row.verdict = 'not published';
    printPropertyEvidence(c.key, { expected, stored: ready.now ?? items, served, mirror: [], ccByItem: new Map(), fields: c.fields, caseless: !!c.caseless });
    return;
  }

  // 5–6. Transferred and received: the mirror holds the same values.
  const mirrorStarted = Date.now();
  const builderActive = await itemsOf(org.orgId, `AND i.lifecycle_status = 'active'`);
  const mirrored = await waitFor(`${c.key} mirror`, async () => {
    const rows = await mirrorOf(org.orgId);
    const d = differences(builderActive, rows, CC_FIELDS, 'id');
    return { done: rows.length === builderActive.length && d.length === 0 && rows.every((r) => r.primary_image_id && r.__photos > 0), rows, d };
  }, MIRROR_DEADLINE_MS, 5_000);
  row.mirrorMs = Date.now() - mirrorStarted;
  row.commandCentre = mirrored.done ? 'exact' : `${mirrored.d?.length ?? '?'} difference(s)`;
  record(`${c.key}: the Command Centre holds every published property, field by field, with its photograph`, mirrored.done,
    `${mirrored.rows?.length ?? 0}/${builderActive.length} in ${secs(mirrored)}`
    + `${mirrored.d?.length ? `; ${mirrored.d.slice(0, 6).join('; ')}` : ''}`
    + `${mirrored.rows?.some((r) => !r.primary_image_id) ? '; a property arrived without its photograph' : ''}`);

  // 7. Read through the Command Centre's own endpoint, photograph included.
  let readOk = 0; let photoOk = 0;
  const ccByItem = new Map();
  for (const item of builderActive) {
    const got = await commandCentre('get_stock_item', { stock_item_id: item.id }, staff.token);
    const r = got.json?.record ?? null;
    const fieldsOk = got.status === 200 && r && differences([item], [r], CC_FIELDS.filter((f) => f !== 'lifecycle_status'), 'id').length === 0;
    if (fieldsOk) readOk += 1;
    // The Command Centre serves a picture by the image the record names,
    // exactly as its card asks for it.
    const imageId = r?.primary_image_id ?? null;
    const image = imageId ? await commandCentre('image_url', { image_id: imageId }, staff.token) : null;
    const url = image?.json?.url ?? null;
    let photoBytes = 0;
    if (url) {
      const bytesServed = await fetch(url).then(async (res) => (res.ok ? new Uint8Array(await res.arrayBuffer()) : null)).catch(() => null);
      if (bytesServed && bytesServed.length > 512) photoOk += 1;
      photoBytes = bytesServed?.length ?? 0;
    }
    ccByItem.set(item.id, { read: !!fieldsOk, photoBytes });
  }
  row.ccRead = `${readOk}/${builderActive.length}`;
  row.ccPhoto = `${photoOk}/${builderActive.length}`;
  record(`${c.key}: the Command Centre's own get_stock_item answers every property's values`, readOk === builderActive.length,
    `${readOk}/${builderActive.length}`);
  record(`${c.key}: the Command Centre serves each property's photograph as image bytes`, photoOk === builderActive.length,
    `${photoOk}/${builderActive.length}`);
  row.verdict = row.parsed === 'exact' && readOk === builderActive.length && photoOk === builderActive.length
    && mirrored.done ? 'PASS' : 'PARTIAL';
  printPropertyEvidence(c.key, {
    expected, stored: ready.now ?? items, served, mirror: mirrored.rows ?? [], ccByItem, fields: c.fields,
    photoSource: (item) => (photoless.some((p) => p.id === item.id) ? 'added through "Add picture"' : 'from the document'),
    caseless: !!c.caseless,
  });
}

// --- The run -------------------------------------------------------------------
let storage = null;
try {
  console.log(`tier-0 formats run=${RUN} cases=${CASES.map((c) => c.key).join(',')}`);
  const reach = await Promise.allSettled([net('reach', 'SELECT 1 AS ok'), cc('reach', 'SELECT 1 AS ok')]);
  if (!record('0: the token reaches both projects', reach.every((r) => r.status === 'fulfilled'),
    reach.map((r) => r.status).join(', '))) throw new Error('cannot reach both projects');
  storage = await storageFor(NETWORK_REF);
  await cleanup(TAG, 'start', storage);
  const staff = await seedStaff(TAG, 'reader', ['listings']);

  for (let i = 0; i < CASES.length; i += BATCH) {
    const batch = CASES.slice(i, i + BATCH);
    console.log(`\n— batch ${i / BATCH + 1}: ${batch.map((c) => c.key).join(', ')}`);
    const settled = await Promise.allSettled(batch.map((c) => runCase(c, storage, staff)));
    settled.forEach((s, j) => {
      if (s.status === 'rejected') record(`${batch[j].key}: the case ran to completion`, false, String(s.reason?.message ?? s.reason).slice(0, 300));
    });
  }
} catch (error) {
  record('the run completed', false, String(error?.message ?? error).slice(0, 400));
} finally {
  console.log('\nSTOCK MATRIX (format · properties · parsed · published · Command Centre · CC read · CC photo · ms import/publish/mirror)');
  for (const r of matrix) {
    console.log(`  ${r.format.padEnd(15)} ${String(r.properties ?? '—').padStart(2)}/${r.expected ?? '—'}  ${String(r.parsed ?? '—').padEnd(18)}`
      + ` ${String(r.published ?? '—').padEnd(5)} ${String(r.commandCentre ?? '—').padEnd(16)} ${String(r.ccRead ?? '—').padEnd(5)}`
      + ` ${String(r.ccPhoto ?? '—').padEnd(5)} ${r.importMs ?? '—'}/${r.publishMs ?? '—'}/${r.mirrorMs ?? '—'}`
      + `${r.remedied ? ` (remedied ${r.remedied})` : ''}  ${r.verdict ?? '—'}`);
  }
  try {
    await cleanup(TAG, 'end', storage);
    const left = await leftovers(TAG);
    record('cleanup: nothing this run made remains on either side',
      Object.values(left.network).every((v) => Number(v) === 0) && Object.values(left.command).every((v) => Number(v) === 0),
      JSON.stringify(left));
  } catch (error) {
    record('cleanup: completed', false, String(error?.message ?? error).slice(0, 300));
  }
  finish('stock-tier0-formats', { run: RUN, cases: CASES.length });
}
